function thermalProcess(data,w,h,opts){
  opts=opts||{};
  var levels=opts.levels!=null?opts.levels:16;
  if(levels<4)levels=4; else if(levels>32)levels=32;
  // ironbow-ish stops: lum 0..1 -> rgb
  var stops=[[0,0,0,4],[0.18,12,4,52],[0.36,60,8,110],[0.55,150,22,96],[0.72,224,64,40],[0.86,250,150,24],[1,255,255,210]];
  function lut(L){ var t=L<0?0:L>1?1:L; for(var i=1;i<stops.length;i++){ if(t<=stops[i][0]){ var a=stops[i-1],b=stops[i]; var f=(t-a[0])/(b[0]-a[0]); return [a[1]+(b[1]-a[1])*f, a[2]+(b[2]-a[2])*f, a[3]+(b[3]-a[3])*f]; } } var l=stops[stops.length-1]; return [l[1],l[2],l[3]]; }
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var p=(y*w+x)*4;
    var L=(0.299*data[p]+0.587*data[p+1]+0.114*data[p+2])/255;
    var c=lut(L);
    out[p]=c[0]; out[p+1]=c[1]; out[p+2]=c[2]; out[p+3]=data[p+3];
  }
  return out;
}

var EXPORTS={thermalProcess:thermalProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ThermalForgePure = EXPORTS; }
